{"packet_id":"D085-01","doc_id":"D085","jurisdiction":"Santa Ana, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Santa Ana Rent Stabilization Ordinance annual cap","requirement":"A landlord may not raise rent above the lower of 3% per year or 80% of CPI; if CPI negative, no increase. Landlords must give written notice of tenant rights at lease start or with any rent increase and may petition for relief.","key_value":"lower of 3% per year or 80% of CPI; 0% if CPI negative","coverage_conditions":"Residential rents; cap does not apply to buildings constructed after February 1, 1995, or to mobile home spaces offered for rent after January 1, 1990.","applicability":{"built_on_or_before":"1995-02-01","built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":false,"other":"mobile home spaces offered after 1990-01-01 are exempt"},"exemptions":"Residential buildings constructed after February 1, 1995; mobile home spaces offered for rent after January 1, 1990.","penalty":null,"effective_date":"2021-11-19","citation":"Santa Ana Rent Stabilization Ordinance","quoted_span":"Increase in residential rents are limited to the lower of 3% per year, or 80% of the percent change in the Consumer Price Index over the most recent 12-month period. If the CPI is negative, no rent increase is permitted.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D085-01","doc_id":"D085","jurisdiction":"Santa Ana, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Santa Ana Just Cause Eviction Ordinance","requirement":"After 30 days, a landlord may not terminate a tenancy without just cause stated in written notice; for no-fault just cause, the landlord must provide 3 months of relocation assistance or waive the final 3 months' rent.","key_value":"3 months' relocation assistance or rent waiver","coverage_conditions":"Tenancies after 30 days; excludes housing produced in the last 15 years, deed-restricted affordable housing, hotel and transient occupancy, hospital and care facilities, dormitories, and shared living quarters.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":false,"other":"Exempts housing produced in the last 15 years; applies after 30 days"},"exemptions":"Housing produced in the last 15 years; deed-restricted affordable housing; hotel and transient occupancy; hospital and care facilities; dormitories; shared living quarters.","penalty":null,"effective_date":"2021-11-19","citation":"Santa Ana Just Cause Eviction Ordinance","quoted_span":"Under a no-fault just cause termination, the owner shall either provide 3 months of relocation assistance or waive payment of rent for the final 3 months of the tenancy.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
